@Command([EditDocument];"1");

@If(companyname = "";@Return(@Do(@Command([EditGotoField];"companyname");@Prompt([Ok];"Alert!";"Please select the company name before proceeding")));"");
@If(System = "";@Return(@Do(@Command([EditGotoField];"System");@Prompt([Ok];"Alert!";"Please select the System before proceeding")));"");
@If(System="BOSS" & Module="";@Return(@Do(@Command([EditGotoField];"Module");@Prompt([Ok];"Alert!";"Please select the module before proceeding")));"");
@If(ProblemDesc = "";@Return(@Do(@Command([EditGotoField];"ProblemDesc");@Prompt([Ok];"Alert!";"Please describe the problem before proceeding")));"");

FIELD DateCreated:= @Now;
FIELD CurrentAction := "Submitted";
FIELD CaseStatus :="In-Progress";
FIELD RemDate := @Adjust(@Today;0;0;2;0;0;0);
@Command([FileSave]);

@MailSend(SendTo;HRHOD:CC;NULL;"HR Applications Problem Reporting : " + @Trim(CaseNo) +" ["+System+"]";NULL;"Please follow this doclink ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument];"1");

@If(Solution = "";@Return(@Do(@Command([EditGotoField];"Solution");@Prompt([Ok];"Alert!";"Please enter the solution before proceeding")));"");
@If(StartDate = "";@Return(@Do(@Command([EditGotoField];"StartDate");@Prompt([Ok];"Alert!";"Please select the date that you have started to work on this issue before proceeding")));"");

FIELD ISGName:=@UserName;
FIELD CurrentAction :="Notified";
FIELD CaseStatus :="Closed";
FIELD CaseStatus_1 :="";
FIELD DateClosed :=@Now;
FIELD RemDate := @Adjust(@Today;0;0;2;0;0;0);

@SetField("AutoClosedDate";@Adjust(DateClosed;0;0;7;0;0;0));

@MailSend(Requestor;MailingList;NULL;"HR Applications Problem Reporting - Completed : " + @Trim(CaseNo) +" ["+System+"]";NULL;"Please follow this doclink ------> ";[IncludeDoclink]);

